    auto catalog=std::make_shared<CommonCatalog>();catalog->actor_ids={"teacher","student"};CommonState seed;seed.identity.world_id[0]=7;seed.identity.tick=10;seed.identity.revision=2;seed.next_instance_id=100;seed.metadata.scenario_id="disciple";seed.metadata.player_actor_id="teacher";seed.request_sequences.insert("student",2);
