    c.state().facts.insert("military:5",{"military:5","military_casualties","military"});c.state().facts.insert("family_death:6",{"family_death:6","family_death","family_life"});FamilyDeathRecord death;death.actor_id="teacher";death.scenario_id="disciple";death.cause_fact_id="military:5";death.battle_id="battle:70";death.world_id=c.state().identity.world_id;death.death_tick=5;death.recorded_tick=5;FamilyDeathState deaths;deaths.deaths.insert("family_death:6",death);
